def build_agent(sandbox):
    beam_w = 0.62
    beam_h = 0.35
    num_beams = 5  # Reduced from 9 to 5 beams
    centers_x = [2.31 + i * 0.62 for i in range(num_beams)]
    y_center = 0.5 + beam_h / 2
    bodies = []

    for i, x in enumerate(centers_x):
        # Buoyancy-optimized middle beam (index 2) with reduced density
        if i == 2:
            density = 20.0  # Lower density for better buoyancy in deep channel
        else:
            density = 35.0
        b = sandbox.add_beam(x, y_center, beam_w, beam_h, angle=0, density=density)
        sandbox.set_material_properties(b, restitution=0.05)
        bodies.append(b)

    # Connect with rigid joints
    for i in range(num_beams - 1):
        anchor_x = (centers_x[i] + centers_x[i + 1]) / 2
        sandbox.add_joint(bodies[i], bodies[i + 1], (anchor_x, y_center), type='rigid')

    return bodies[-1]

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    if front_x >= target_x + 0.1:
        for b in sandbox.bodies:
            if b.active:
                b.linearVelocity = (0, 0)
                b.angularVelocity = 0
        return

    THRUST_F = 520.0
    LIFT_F = 300.0  # Reduced lift force to stay within joint limits
    in_deep_channel = 16.5 <= front_x <= 19.5

    for b in sandbox.bodies:
        if not b.active:
            continue

        # Apply thrust only to the last two beams (paddles)
        if b not in (sandbox.bodies[-1], sandbox.bodies[-2]):
            continue

        fx = THRUST_F
        fy = 0.0

        if in_deep_channel:
            fy = LIFT_F  # Buoyancy compensation in deep channel

        vx = b.linearVelocity.x

        # Thrust modulation based on velocity to prevent force spikes
        if vx > 1.8:
            fx *= 0.1
        elif vx > 1.0:
            fx *= 0.4

        sandbox.apply_force(b, fx, fy, step_count=step_count)
